CREATE TABLE invoices(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,user_id BINARY(16) NOT NULL,bill_id BINARY(16) NOT NULL UNIQUE,invoice_number VARCHAR(50) NOT NULL UNIQUE,customer_name VARCHAR(150) NOT NULL,customer_email VARCHAR(254) NOT NULL,billing_address VARCHAR(1000),tax_registration_number VARCHAR(50),subtotal DECIMAL(12,2) NOT NULL,tax_amount DECIMAL(12,2) NOT NULL,total_amount DECIMAL(12,2) NOT NULL,currency VARCHAR(3) NOT NULL,status VARCHAR(20) NOT NULL,issue_date DATE NOT NULL,due_date DATE NOT NULL,issued_at TIMESTAMP(6),paid_at TIMESTAMP(6),created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL);CREATE INDEX idx_invoices_tenant_created ON invoices(tenant_id,created_at);CREATE INDEX idx_invoices_user ON invoices(user_id);
